// The files that list the server where people look for one, generated by listings.mjs
// from package.json and the catalogue the server runs on:
//
//   plugins/quilly/.claude-plugin/plugin.json   the Claude Code plugin, which is also what Anthropic's directory lists
//   .claude-plugin/marketplace.json             this repository as a plugin marketplace
//   packages/quilly-mcp/server.json             the entry in the MCP registry
//
// Unlike the desktop-extension manifest they are committed, because Claude Code and
// the directory read them from the repository.
import { AGENT_PLUGIN } from '../../../src/shared/agentProtocol';
import { ENV, SUMMARY, USER_CONFIG, USER_CONFIG_ENV } from './catalog';
import { ICON, links, type PackageInfo } from './manifest';

/** Name of the plugin and of the server inside it. */
const PLUGIN_NAME = AGENT_PLUGIN.name;
/** The plugin's folder, relative to the repository root. */
export const PLUGIN_DIR = `plugins/${PLUGIN_NAME}`;
/** Path of the icon inside the plugin's folder. */
export const PLUGIN_ICON = ICON;

const DISPLAY_NAME = 'Quilly';
const PRIVACY_POLICY = 'https://gegham-khachatryan.github.io/quilly/privacy';
const REGISTRY_SCHEMA = 'https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json';
/** The registry rejects a longer description. */
const REGISTRY_DESCRIPTION_MAX = 100;

export function buildPlugin(pkg: PackageInfo) {
  const { repository, author, documentation, support } = links(pkg);
  return {
    name: PLUGIN_NAME,
    displayName: DISPLAY_NAME,
    version: pkg.version,
    description: SUMMARY,
    author,
    homepage: repository,
    repository,
    license: pkg.license,
    keywords: pkg.keywords,
    icon: `./${PLUGIN_ICON}`,
    documentationUrl: documentation,
    supportUrl: support,
    privacyPolicyUrl: PRIVACY_POLICY,
    userConfig: USER_CONFIG,
    mcpServers: {
      // The directory only lists a plugin whose package launcher names an exact version.
      [PLUGIN_NAME]: { command: 'npx', args: ['-y', `${pkg.name}@${pkg.version}`], env: USER_CONFIG_ENV },
    },
  };
}

export function buildMarketplace(pkg: PackageInfo) {
  // The settings page tells people to install from this repository, so it has to be the one the marketplace file is in.
  if (!pkg.repository.url.endsWith(`github.com/${AGENT_PLUGIN.repository}`)) {
    throw new Error(`AGENT_PLUGIN.repository is ${AGENT_PLUGIN.repository}, but package.json points at ${pkg.repository.url}.`);
  }
  return {
    name: AGENT_PLUGIN.marketplace,
    description: 'Quilly for Claude Code: read the Google Meet transcripts Quilly records.',
    owner: links(pkg).author,
    // No version here: the plugin manifest's version is the one Claude Code installs by.
    plugins: [{ name: PLUGIN_NAME, source: `./${PLUGIN_DIR}`, description: SUMMARY, category: 'productivity' }],
  };
}

export function buildRegistryEntry(pkg: PackageInfo) {
  if (SUMMARY.length > REGISTRY_DESCRIPTION_MAX) {
    throw new Error(`SUMMARY is ${SUMMARY.length} characters; the MCP registry accepts at most ${REGISTRY_DESCRIPTION_MAX}.`);
  }
  return {
    $schema: REGISTRY_SCHEMA,
    name: pkg.mcpName,
    title: DISPLAY_NAME,
    description: SUMMARY,
    version: pkg.version,
    repository: { url: pkg.repository.url, source: 'github', subfolder: pkg.repository.directory },
    websiteUrl: pkg.homepage,
    packages: [
      {
        registryType: 'npm',
        identifier: pkg.name,
        version: pkg.version,
        transport: { type: 'stdio' },
        environmentVariables: [
          { name: ENV.token, description: `${USER_CONFIG.token.title}. ${USER_CONFIG.token.description}`, format: 'string', isRequired: true, isSecret: true },
          { name: ENV.port, description: USER_CONFIG.port.description, format: 'number', default: String(USER_CONFIG.port.default) },
        ],
      },
    ],
  };
}
